import { uniqueStrings } from './unique_repeat.mjs';

// Basic dedup preserving order
console.log(JSON.stringify(uniqueStrings(['a','b','a','c','b'])));

// Case sensitivity
console.log(JSON.stringify(uniqueStrings(['Foo','foo','FOO','Foo'])));

// Whitespace not trimmed
console.log(JSON.stringify(uniqueStrings([' a','a','a ',' a'])));

// Empty input
console.log(JSON.stringify(uniqueStrings([])));

// Input not mutated
const input = ['x','y','x'];
const out = uniqueStrings(input);
console.log('input unchanged:', JSON.stringify(input) === JSON.stringify(['x','y','x']));
console.log('new array:', out !== input);
"

